// v1 clients expect:
// { id, username, email }
// v2 clients expect:
// { id, username, email, displayName, avatarUrl }

public class UserResponseV2
{
    public Guid Id { get; set; }
    public string Username { get; set; }
    public string Email { get; set; }
    public string? DisplayName { get; set; }  // New, nullable
    public string? AvatarUrl { get; set; }    // New, nullable
}

// v1 serializer ignores unknown fields if using JsonIgnoreCondition.WhenWritingNull

// ASP.NET Core versioning via route constraints
[ApiController]
[Route("v{version:apiVersion}/users")]
[ApiVersion("1.0")]
public class UsersV1Controller : ControllerBase { }

[ApiController]
[Route("v{version:apiVersion}/users")]
[ApiVersion("2.0")]
public class UsersV2Controller : ControllerBase { }

// Global deprecation filter
public class DeprecationFilter : IResultFilter
{
    public void OnResultExecuting(ResultExecutingContext context)
    {
        if (context.HttpContext.GetRequestedApiVersion() == new ApiVersion(1,0))
        {
            context.HttpContext.Response.Headers.Sunset = "2026-10-31";
        }
    }
}
